package com.askepedia.entity;

import java.time.Instant;

/**
 * Domain entity representing a row in the 'wiki_article' database table.
 */
public record Article(
    Long articleId,
    String title,
    String sourceUrl,
    String content,
    Instant fetchedAt
) {
    /**
     * Convenience factory method for creating a new Article prior to database insertion
     * (where articleId is auto-generated by the database sequence).
     */
    public static Article of(String title, String sourceUrl, String content) {
        return new Article(null, title, sourceUrl, content, Instant.now());
    }
}
